<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import UiAlert from'../../Components/UiAlert.vue';import UiButton from'../../Components/UiButton.vue';import UiCard from'../../Components/UiCard.vue';import{Head,useForm}from'@inertiajs/vue3';const form=useForm({name:'',event_type:'wedding',privacy:'private',location:'',membership_limit:500,access_options:['partial_access','full_access'],face_recognition_enabled:true,allow_guest_upload:false,watermark_enabled:false});</script><template><AppShell><Head title="Create event"/><div class="lp-page-narrow"><PageHeader eyebrow="New event" title="Set the stage" description="Configure access and privacy before the first photograph enters processing."/><UiCard class="mt-8"><form class="space-y-5" @submit.prevent="form.post('/groups')"><label class="lp-label">Event name<input v-model="form.name" class="field mt-2" placeholder="Aarav & Mira — Mumbai" required><span v-if="form.errors.name" class="lp-error">{{form.errors.name}}</span></label><div class="grid gap-5 md:grid-cols-2"><label class="lp-label">Event type<select v-model="form.event_type" class="field mt-2"><option value="wedding">Wedding</option><option value="corporate">Corporate</option><option value="sports">Sports</option><option value="other">Other</option></select></label><label class="lp-label">Privacy<select v-model="form.privacy" class="field mt-2"><option value="private">Private</option><option value="link_only">Invitation only</option><option value="public">Public</option></select></label></div><label class="lp-label">Location<input v-model="form.location" class="field mt-2" placeholder="Mumbai, Maharashtra"></label><fieldset class="space-y-3 rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm"><legend class="px-1 font-semibold">Event features</legend><label class="flex gap-3"><input v-model="form.face_recognition_enabled" type="checkbox" class="accent-indigo">Enable consent-led My Photos discovery</label><label class="flex gap-3"><input v-model="form.allow_guest_upload" type="checkbox" class="accent-indigo">Allow participant uploads</label><label class="flex gap-3"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Apply studio watermark</label></fieldset><UiAlert v-if="Object.keys(form.errors).length" tone="error">Please review the highlighted event details.</UiAlert><UiButton type="submit" :loading="form.processing">Create event</UiButton></form></UiCard></div></AppShell></template>
